#include <iostream>
#include <utility>

int main() {
    int num;
    if (!(std::cin >> num)) return 0;

    int d_first = num / 1000;
    int d_hundred = (num / 100) % 10;
    int d_ten = (num / 10) % 10;
    int d_last = num % 10;
    int sum = d_first + d_hundred + d_ten + d_last;

    std::cout << sum << " " << d_first << " " << d_last << "\n";

    // Variable swap demonstration
    int a = d_first;
    int b = d_last;
    // Arithmetic swap
    a = a + b;
    b = a - b;
    a = a - b;
    std::cout << a << " " << b << "\n";

    return 0;
}

body.vi:
Các bài toán thực tế như quản lý sinh viên (họ tên, điểm) hoặc bảng lương nhân viên (họ tên, hệ số lương, phụ cấp, BHXH) đòi hỏi nhóm các thuộc tính có kiểu dữ liệu khác nhau lại thành một đơn vị logic. Trong C++, `struct` cho phép định nghĩa kiểu dữ liệu bản ghi một cách trực quan và trong sáng:
```cpp
struct Employee {
    std::string name;
    double salary_coeff;
    double allowance_pct;
    double insurance_pct;
};
```
Sử dụng struct giúp mã nguồn module hóa, tránh việc phải duy trì các biến rời rạc như `name1, name2, coeff1, coeff2`, đồng thời kết hợp tốt với `std::string` để xử lý chuỗi ký tự mà không sợ lỗi tràn bộ đệm như mảng ký tự `char[]` trong C cổ điển.

body.en:
Real-world problems such as managing student transcripts or employee payroll (name, salary coefficient, allowance percentage, social insurance) require grouping attributes of different types into a single logical unit. In C++, `struct` facilitates concise and safe record encapsulation:
```cpp
struct Employee {
    std::string name;
    double salary_coeff;
    double allowance_pct;
    double insurance_pct;
};
```
Using structs promotes modularity and prevents managing fragmented scalar variables like `name1, name2`, while pairing seamlessly with `std::string` to prevent legacy C `char[]` buffer overflows.

example.code:
#include <iostream>
#include <iomanip>
#include <cmath>
#include <string>

struct Employee {
    std::string name;
    double coeff;
    double allowance_pct;
    double insurance_pct;

    double net_salary(double base_rate) const {
        double base = coeff * base_rate;
        double allowance = base * (allowance_pct / 100.0);
        double insurance = base * (insurance_pct / 100.0);
        return base + allowance - insurance;
    }
};

int main() {
    double r;
    if (!(std::cin >> r)) return 0;

    const double pi = std::acos(-1.0);
    double s = 4.0 * pi * r * r;
    double v = (r * s) / 3.0;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << s << " " << v << "\n";

    Employee emp;
    if (std::cin >> emp.name >> emp.coeff >> emp.allowance_pct >> emp.insurance_pct) {
        double net = emp.net_salary(1000.0);
        std::cout << emp.name << " " << net << "\n";
    }

    return 0;
}
